{"file_path":"src/parser.js","content":"/**
 * The parser for the configuration document. Every directive fits on one line,
 * so the document is parsed one line at a time and each line is scanned with a
 * small cursor.
 *
 * A parsed value is a node: `{ k, v }` where `k` is one of `table`, `array`,
 * `string`, `integer`, `float` and `boolean`. A table keeps a Map so that key
 * order stays under our control, and an array of tables carries `aot: true`.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(`error: line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const BARE = /[A-Za-z0-9_-]/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const NUM_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'

function newTable() {
  return { k: 'table', v: new Map(), explicit: false }
}

function joinPath(prefix, name) {
  return prefix ? `${prefix}.${name}` : name
}

/** A cursor over a single line. */
class Line {
  constructor(text, lineNo) {
    this.s = text
    this.i = 0
    this.line = lineNo
  }

  err(reason) {
    return new ParseError(this.line, reason)
  }

  get c() {
    return this.s[this.i]
  }

  atEnd() {
    return this.i >= this.s.length
  }

  /** End of the line, or the start of a comment, which ends it as well. */
  atLogicalEnd() {
    return this.atEnd() || isComment(this.c)
  }

  skipWs() {
    while (!this.atEnd() && isWs(this.c)) this.i++
  }

  /** A bare word or a quoted string. */
  parseName() {
    if (this.c === '"') return this.parseBasicString()
    if (this.c === "'") return this.parseLiteralString()
    let word = ''
    while (!this.atEnd() && BARE.test(this.c)) {
      word += this.c
      this.i++
    }
    if (word === '') throw this.err('expected a name')
    return word
  }

  /** Names joined by `.`, with spaces and tabs allowed around each `.`. */
  parseDottedName() {
    const names = [this.parseName()]
    for (;;) {
      const save = this.i
      this.skipWs()
      if (this.c !== '.') {
        this.i = save
        return names
      }
      this.i++
      this.skipWs()
      names.push(this.parseName())
    }
  }

  parseBasicString() {
    this.i++ // the opening quote
    let out = ''
    while (!this.atEnd()) {
      const c = this.c
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        this.i++
        if (this.atEnd()) break
        const e = this.c
        switch (e) {
          case '"': out += '"'; this.i++; break
          case '\\': out += '\\'; this.i++; break
          case 'n': out += '\n'; this.i++; break
          case 't': out += '\t'; this.i++; break
          case 'r': out += '\r'; this.i++; break
          case '0': out += '\0'; this.i++; break
          case 'u': {
            const hex = this.s.substr(this.i + 1, 4)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw this.err('invalid escape \\u')
            out += String.fromCharCode(parseInt(hex, 16))
            this.i += 5
            break
          }
          default:
            throw this.err(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      this.i++
    }
    throw this.err('unterminated string')
  }

  parseLiteralString() {
    this.i++ // the opening quote
    let out = ''
    while (!this.atEnd()) {
      if (this.c === "'") {
        this.i++
        return out
      }
      out += this.c
      this.i++
    }
    throw this.err('unterminated string')
  }
}

class Parser {
  constructor() {
    this.root = newTable()
    this.root.explicit = true
    this.current = this.root
    this.currentPath = ''
  }

  parse(lines) {
    for (let n = 0; n < lines.length; n++) {
      const p = new Line(lines[n], n + 1)
      p.skipWs()
      if (p.atLogicalEnd()) continue
      if (p.c === '[') this.header(p)
      else this.assignment(p)
    }
    return this.root
  }

  /**
   * Walk one step of a dotted path, creating a table when nothing is there.
   * An array of tables is walked through by its last element.
   */
  step(node, name, path, p) {
    let child = node.v.get(name)
    if (child === undefined) {
      child = newTable()
      node.v.set(name, child)
    }
    if (child.k === 'array' && child.aot && child.v.length > 0) {
      child = child.v[child.v.length - 1]
    }
    if (child.k !== 'table') throw p.err(`${path} is not a table`)
    return child
  }

  header(p) {
    p.i++ // '['
    let aot = false
    if (p.c === '[') {
      aot = true
      p.i++
    }
    p.skipWs()
    const names = p.parseDottedName()
    p.skipWs()
    if (p.c !== ']') throw p.err('unterminated table header')
    p.i++
    if (aot) {
      if (p.c !== ']') throw p.err('unterminated table header')
      p.i++
    }
    p.skipWs()
    if (!p.atLogicalEnd()) throw p.err('trailing text after a table header')

    let node = this.root
    let path = ''
    for (let i = 0; i < names.length - 1; i++) {
      path = joinPath(path, names[i])
      node = this.step(node, names[i], path, p)
    }
    const last = names[names.length - 1]
    path = joinPath(path, last)

    let cur = node.v.get(last)
    if (aot) {
      if (cur === undefined) {
        cur = { k: 'array', v: [], aot: true }
        node.v.set(last, cur)
      }
      if (cur.k !== 'array' || !cur.aot) throw p.err(`${path} is not an array of tables`)
      const fresh = newTable()
      cur.v.push(fresh)
      this.current = fresh
    } else {
      if (cur === undefined) {
        cur = newTable()
        node.v.set(last, cur)
      }
      if (cur.k !== 'table') throw p.err(`${path} is not a table`)
      if (cur.explicit) throw p.err(`table ${path} is defined twice`)
      cur.explicit = true
      this.current = cur
    }
    this.currentPath = path
  }

  assignment(p) {
    const names = p.parseDottedName()
    p.skipWs()
    if (p.c !== '=') throw p.err('expected key = value')
    p.i++
    p.skipWs()

    let node = this.current
    let path = this.currentPath
    for (let i = 0; i < names.length - 1; i++) {
      path = joinPath(path, names[i])
      node = this.step(node, names[i], path, p)
    }
    const last = names[names.length - 1]
    path = joinPath(path, last)

    const value = this.value(p, path)
    p.skipWs()
    if (!p.atLogicalEnd()) throw p.err('trailing text after a value')

    if (node.v.has(last)) throw p.err(`key ${path} is defined twice`)
    node.v.set(last, value)
  }

  value(p, path) {
    if (p.atLogicalEnd() || p.c === ',' || p.c === ']' || p.c === '}') {
      throw p.err('expected a value')
    }
    if (p.c === '"') return { k: 'string', v: p.parseBasicString() }
    if (p.c === "'") return { k: 'string', v: p.parseLiteralString() }
    if (p.c === '[') return this.array(p, path)
    if (p.c === '{') return this.inlineTable(p, path)

    let word = ''
    while (!p.atEnd() && !isWs(p.c) && p.c !== ',' && p.c !== ']' && p.c !== '}') {
      word += p.c
      p.i++
    }
    if (word === 'true') return { k: 'boolean', v: true }
    if (word === 'false') return { k: 'boolean', v: false }
    if (NUM_RE.test(word)) {
      const n = Number(word.replace(/_/g, ''))
      return { k: INT_RE.test(word) ? 'integer' : 'float', v: n }
    }
    throw p.err(`invalid value ${word}`)
  }

  array(p, path) {
    p.i++ // '['
    const items = []
    for (;;) {
      p.skipWs()
      if (p.atLogicalEnd()) throw p.err('unterminated array')
      if (p.c === ']') {
        p.i++
        break
      }
      items.push(this.value(p, `${path}[${items.length}]`))
      p.skipWs()
      if (p.atLogicalEnd()) throw p.err('unterminated array')
      if (p.c === ']') {
        p.i++
        break
      }
      if (p.c !== ',') throw p.err('unterminated array')
      p.i++
    }
    return { k: 'array', v: items, aot: false }
  }

  inlineTable(p, path) {
    p.i++ // '{'
    const table = newTable()
    let afterComma = false
    for (;;) {
      p.skipWs()
      if (p.atLogicalEnd()) throw p.err('unterminated inline table')
      if (p.c === '}' && !afterComma) {
        p.i++
        break
      }
      const names = p.parseDottedName()
      p.skipWs()
      if (p.c !== '=') throw p.err('expected = in an inline table')
      p.i++
      p.skipWs()

      let node = table
      let sub = path
      for (let i = 0; i < names.length - 1; i++) {
        sub = joinPath(sub, names[i])
        node = this.step(node, names[i], sub, p)
      }
      const last = names[names.length - 1]
      sub = joinPath(sub, last)

      const value = this.value(p, sub)
      if (node.v.has(last)) throw p.err(`key ${sub} is defined twice`)
      node.v.set(last, value)

      p.skipWs()
      if (p.atLogicalEnd()) throw p.err('unterminated inline table')
      if (p.c === '}') {
        p.i++
        break
      }
      if (p.c !== ',') throw p.err('unterminated inline table')
      p.i++
      afterComma = true
    }
    return table
  }
}

/** Split the input into lines, dropping the empty tail a newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parseDocument(input) {
  return new Parser().parse(splitLines(input))
}
