{"file_path":"src/render.js","content":"/** Rendering of a parsed document, as canonical JSON and as a list of keys. */

/** Compare two strings by code point, ascending. */
export function compareKeys(a, b) {
  const A = Array.from(a)
  const B = Array.from(b)
  const n = Math.min(A.length, B.length)
  for (let i = 0; i < n; i++) {
    const x = A[i].codePointAt(0)
    const y = B[i].codePointAt(0)
    if (x !== y) return x - y
  }
  return A.length - B.length
}

function sortedKeys(table) {
  return Array.from(table.v.keys()).sort(compareKeys)
}

function render(node, indent) {
  switch (node.k) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const inner = indent + '  '
      const parts = keys.map(
        (k) => `${inner}${JSON.stringify(k)}: ${render(node.v.get(k), inner)}`
      )
      return `{\n${parts.join(',\n')}\n${indent}}`
    }
    case 'array': {
      if (node.v.length === 0) return '[]'
      const inner = indent + '  '
      const parts = node.v.map((item) => `${inner}${render(item, inner)}`)
      return `[\n${parts.join(',\n')}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    default:
      return JSON.stringify(node.v)
  }
}

export function toJson(root) {
  return render(root, '') + '\n'
}

function typeName(node) {
  return node.k
}

function walk(node, path, out) {
  if (node.k === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.v.get(key)
      const childPath = path ? `${path}.${key}` : key
      out.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, out)
    }
  } else if (node.k === 'array') {
    for (let i = 0; i < node.v.length; i++) {
      const child = node.v[i]
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, out)
    }
  }
}

export function toKeys(root) {
  const out = []
  walk(root, '', out)
  return out.map((line) => line + '\n').join('')
}
