}

/**
 * Parser class - defined before use
 */
class Parser {
  constructor(lines) {
    this.lines = lines
    this.root = {}
    this.current = this.root
    this.currentPath = []
    this.lineNum = 0
    this.definedKeys = new Set()
    this.definedTables = new Set()
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Strip comments and handle quoted strings
    const trimmedLine = this.stripComments(line)

    if (this.isBlank(trimmedLine)) {
      return
    }

    if (trimmedLine[0] === '[') {
      this.parseHeader(trimmedLine)
    } else {
      this.parseKeyValue(trimmedLine)
    }
  }

  stripComments(line) {
    let inBasicString = false
    let inLiteralString = false
    let escaped = false
    let result = ''

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (escaped) {
        result += char
        escaped = false
        continue
      }

      if (char === '\\' && inBasicString) {
        result += char
        escaped = true
        continue
      }

      if (char === '"' && !inLiteralString) {
        inBasicString = !inBasicString
        result += char
        continue
      }

      if (char === "'" && !inBasicString) {
        inLiteralString = !inLiteralString
        result += char
        continue
      }

      if ((char === '#' || char === ';') && !inBasicString && !inLiteralString) {
        // Check if preceded by whitespace
        // If not preceded by whitespace, it's part of the value (which will be invalid)
        if (result.length > 0 && !/[\s]/.test(result[result.length - 1])) {
          // Not preceded by whitespace, include it
          result += char
        } else {
          // Preceded by whitespace or at start, it's a comment
          break
        }
        continue
      }

      result += char
    }

    return result
  }

  isBlank(line) {
    // Check if line is only whitespace
    return /^\s*$/.test(line)
  }

  parseHeader(line) {
    let i = 0

    // Skip leading whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    if (line[i] !== '[') {
      throw this.error('expected [ at start of header')
    }
    i++

    // Check for array of tables
    let isArray = false
    if (line[i] === '[') {
      isArray = true
      i++
    }

    // Skip whitespace
    while (i < line.length && /[\s]/.test(line[i])) i++

    // Parse the name
    const names = []
    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === ']') break

      // Parse a name
      let name
      if (line[i] === '"') {
        // Basic string
        i++
        let str = ''
        let escaped = false
        while (i < line.length) {
          if (escaped) {
            str += line[i]
            escaped = false
          } else if (line[i] === '\\') {
