        i++
      } else if (line[i] === "'") {
        // Literal string
        i++
        let str = ''
        while (i < line.length && line[i] !== "'") {
          str += line[i]
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        name = str
        i++
      } else {
        // Bare word
        let word = ''
        while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
          word += line[i]
          i++
        }
        if (word === '') {
          throw this.error('expected a name')
        }
        name = word
      }

      names.push(name)

