  }

  applyHeader(names, isArray) {
    const path = names.join('.')

    if (isArray) {
      // Array of tables
      let obj = this.root
      const fullPath = []

      for (let i = 0; i < names.length - 1; i++) {
        fullPath.push(names[i])
        const key = names[i]
        if (!(key in obj)) {
          obj[key] = {}
        } else if (typeof obj[key] !== 'object' || Array.isArray(obj[key])) {
