        let word = ''
        while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
          word += line[i]
          i++
        }
        if (word === '') {
          throw this.error('expected a name')
        }
        key = word
      }

      keys.push(key)

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

