        switch (char) {
          case 'n':
            str += '\n'
            break
          case 't':
            str += '\t'
            break
          case 'r':
            str += '\r'
            break
          case '\\':
            str += '\\'
            break
          case '"':
            str += '"'
            break
          case '0':
            str += '\0'
            break
          case 'u':
            // Parse \uXXXX
            i++
            if (i + 3 >= line.length) {
              throw this.error('invalid escape \\u')
            }
            const hex = line.substr(i, 4)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw this.error('invalid escape \\u')
            }
            str += String.fromCharCode(parseInt(hex, 16))
            i += 3
            break
          default:
            throw this.error(`invalid escape \\${char}`)
        }
        escaped = false
      } else if (line[i] === '\\') {
        escaped = true
      } else if (line[i] === '"') {
        return { value: str, i: i + 1 }
      } else {
        str += line[i]
      }
      i++
    }

    throw this.error('unterminated string')
  }

  parseLiteralString(line, startI) {
    let i = startI + 1
    let str = ''

    while (i < line.length && line[i] !== "'") {
      str += line[i]
      i++
    }

    if (i >= line.length) {
      throw this.error('unterminated string')
    }

    return { value: str, i: i + 1 }
  }

  parseArray(line, startI) {
    let i = startI + 1
    const values = []

    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === ']') {
        return { value: values, i: i + 1 }
      }

      if (values.length > 0) {
        // Expect comma
        if (line[i] !== ',') {
          throw this.error('expected , in array')
        }
        i++

        // Skip whitespace
        while (i < line.length && /[\s]/.test(line[i])) i++

        if (line[i] === ']') {
          return { value: values, i: i + 1 }
        }
      }

      const result = this.parseValue(line, i)
      values.push(result.value)
      i = result.i

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++
    }

    throw this.error('unterminated array')
  }

  parseInlineTable(line, startI) {
    let i = startI + 1
    const table = {}

    while (i < line.length) {
      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      if (line[i] === '}') {
        return { value: table, i: i + 1 }
      }

      if (Object.keys(table).length > 0) {
        // Expect comma
        if (line[i] !== ',') {
          throw this.error('expected , in inline table')
        }
        i++

        // Skip whitespace
        while (i < line.length && /[\s]/.test(line[i])) i++
      }

      // Parse key
      let key
      if (line[i] === '"') {
        i++
        let str = ''
        let escaped = false
        while (i < line.length) {
          if (escaped) {
            str += line[i]
            escaped = false
          } else if (line[i] === '\\') {
            escaped = true
          } else if (line[i] === '"') {
            break
          } else {
            str += line[i]
          }
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        key = this.decodeBasicString(str)
        i++
      } else if (line[i] === "'") {
        i++
        let str = ''
        while (i < line.length && line[i] !== "'") {
          str += line[i]
          i++
        }
        if (i >= line.length) {
          throw this.error('unterminated string')
        }
        key = str
        i++
      } else {
        let word = ''
        while (i < line.length && /[A-Za-z0-9_-]/.test(line[i])) {
          word += line[i]
          i++
        }
        if (word === '') {
          throw this.error('expected a name')
        }
        key = word
      }

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      // Expect =
      if (i >= line.length || line[i] !== '=') {
        throw this.error('expected = in an inline table')
      }
      i++

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++

      // Parse value
      const result = this.parseValue(line, i)
      table[key] = result.value
      i = result.i

      // Skip whitespace
      while (i < line.length && /[\s]/.test(line[i])) i++
    }

    throw this.error('unterminated inline table')
  }

  decodeBasicString(str) {
    let result = ''
    let i = 0
    let escaped = false

    while (i < str.length) {
      if (escaped) {
        const char = str[i]
        switch (char) {
          case 'n':
            result += '\n'
            break
          case 't':
            result += '\t'
            break
          case 'r':
            result += '\r'
            break
          case '\\':
            result += '\\'
            break
          case '"':
            result += '"'
            break
          case '0':
            result += '\0'
            break
          case 'u':
            // Parse \uXXXX
            i++
            if (i + 3 >= str.length) {
              throw this.error('invalid escape \\u')
            }
            const hex = str.substr(i, 4)
            if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
              throw this.error('invalid escape \\u')
            }
            result += String.fromCharCode(parseInt(hex, 16))
            i += 3
            break
          default:
            throw this.error(`invalid escape \\${char}`)
        }
        escaped = false
      } else if (str[i] === '\\') {
        escaped = true
      } else {
        result += str[i]
      }
      i++
    }

    return result
  }

  error(msg) {
    const error = new Error(`error: line ${this.lineNum + 1}: ${msg}`)
    error.isParseError = true
    return error
  }
}

// Parse the document
try {
  const document = parseDocument(input)

  if (mode === 'json') {
    outputJson(document)
  } else {
    outputKeys(document)
  }
} catch (error) {
  process.stderr.write(error.message + '\n')
  process.exit(2)
}

/**
 * Parse the TOML document
 */
function parseDocument(input) {
  // Split into lines and drop empty tail
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parser = new Parser(lines)
  return parser.parse()
}

/**
 * Output as JSON
 */
function outputJson(obj) {
  const sorted = sortObjectKeys(obj)
  const json = JSON.stringify(sorted, null, 2)
  process.stdout.write(json + '\n')
}

/**
 * Recursively sort all object keys in ascending order
 */
function sortObjectKeys(value) {
  if (Array.isArray(value)) {
    return value.map(item => sortObjectKeys(item))
  } else if (value !== null && typeof value === 'object') {
    const sorted = {}
    const keys = Object.keys(value).sort()
    for (const key of keys) {
      sorted[key] = sortObjectKeys(value[key])
    }
    return sorted
  }
  return value
}

/**
 * Output keys
 */
function outputKeys(obj) {
  const lines = []
  walkKeys(obj, '', lines)
  process.stdout.write(lines.join('\n') + (lines.length > 0 ? '\n' : ''))
}

function walkKeys(obj, path, lines) {
  if (Array.isArray(obj)) {
    lines.push(`${path} array`)
    for (let i = 0; i < obj.length; i++) {
      const childPath = `${path}[${i}]`
      walkKeys(obj[i], childPath, lines)
    }
  } else if (typeof obj === 'object' && obj !== null) {
    const isTable = path !== ''
    if (isTable) {
      lines.push(`${path} table`)
    }

    const keys = Object.keys(obj).sort()
    for (const key of keys) {
      const childPath = path ? `${path}.${key}` : key
      const child = obj[key]

      if (Array.isArray(child)) {
        lines.push(`${childPath} array`)
        for (let i = 0; i < child.length; i++) {
          const itemPath = `${childPath}[${i}]`
          walkKeys(child[i], itemPath, lines)
        }
      } else if (typeof child === 'object' && child !== null) {
        lines.push(`${childPath} table`)
        const childKeys = Object.keys(child).sort()
        for (const childKey of childKeys) {
          const grandchildPath = `${childPath}.${childKey}`
          const grandchild = child[childKey]
          walkKeysHelper(grandchild, grandchildPath, lines)
        }
      } else {
        walkKeysHelper(child, childPath, lines)
      }
    }
  }
}

function walkKeysHelper(value, path, lines) {
  if (Array.isArray(value)) {
    lines.push(`${path} array`)
    for (let i = 0; i < value.length; i++) {
      const itemPath = `${path}[${i}]`
      walkKeys(value[i], itemPath, lines)
    }
  } else if (typeof value === 'object' && value !== null) {
    lines.push(`${path} table`)
    const keys = Object.keys(value).sort()
    for (const key of keys) {
      const childPath = `${path}.${key}`
      walkKeysHelper(value[key], childPath, lines)
    }
  } else if (typeof value === 'string') {
    lines.push(`${path} string`)
  } else if (typeof value === 'number') {
    if (Number.isInteger(value)) {
      lines.push(`${path} integer`)
    } else {
      lines.push(`${path} float`)
    }
  } else if (typeof value === 'boolean') {
    lines.push(`${path} boolean`)
  }
}

