import { readFileSync, writeSync } from 'node:fs'
import { ParseError, parseDocument } from './parser.js'
import { toJson, toKeys } from './render.js'

function writeAll(fd, text) {
  const buf = Buffer.from(text, 'utf8')
  let off = 0
  while (off < buf.length) {
    try {
      off += writeSync(fd, buf, off, buf.length - off)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EPIPE') return
      throw e
    }
  }
}

function fail(message) {
  writeAll(2, `error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || (argv[0] !== 'json' && argv[0] !== 'keys')) {
  fail('usage: cli.js json|keys')
}
const mode = argv[0]

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let output
try {
  const document = parseDocument(input)
  output = mode === 'json' ? toJson(document) : toKeys(document)
} catch (error) {
  if (error instanceof ParseError) {
    writeAll(2, error.message + '\n')
    process.exit(2)
  }
  throw error
}

writeAll(1, output)
process.exit(0)

